import numpy as np
import time


def _R(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = np.convolve(h, h)
    L = np.concatenate(([0.0], L, [0.0]))
    sq = np.sum(L[:-1] * L[:-1] + L[:-1] * L[1:] + L[1:] * L[1:]) / 3.0
    l1 = s * s
    linf = L.max()
    if linf <= 0:
        return 0.0
    return sq / (l1 * linf)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    best = None
    best_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            best = s.copy()
            best_r = _R(best)

    # Build diverse candidate shapes at several N, pick best.
    cands = []
    for N in (20, 30, 40, 50):
        x = np.linspace(-1, 1, N)
        for p in (1.0, 2.0, 3.0, 4.0, 6.0, 8.0):
            cands.append(np.clip(1.0 - x * x, 0.0, None) ** p)
        for w in (0.2, 0.3, 0.4, 0.5, 0.7):
            cands.append(np.exp(-(x / w) ** 2))
        cands.append(np.cos(x * np.pi / 2) ** 2)
        cands.append(np.ones(N))

    for c in cands:
        if c.sum() <= 0:
            continue
        r = _R(c)
        if r > best_r:
            best_r = r
            best = c.copy()

    if best is None:
        best = np.ones(50)
        best_r = _R(best)

    # Random-restart coordinate hill climbing with a "flattening" bias toward
    # equalizing the peak plateau (which is what drives R up).
    rng = np.random.default_rng(12345)

    def refine(cur, cur_r, rng, deadline):
        n = cur.size
        step = 0.5
        while time.process_time() < deadline:
            improved = False
            order = rng.permutation(n)
            for i in order:
                for delta in (step, -step):
                    trial = cur.copy()
                    trial[i] = max(0.0, trial[i] + delta)
                    if trial.sum() <= 0:
                        continue
                    r = _R(trial)
                    if r > cur_r:
                        cur = trial
                        cur_r = r
                        improved = True
                        break
            if not improved:
                step *= 0.5
                if step < 1e-7:
                    break
        return cur, cur_r

    cur, cur_r = refine(best.copy(), best_r, rng, deadline)
    if cur_r > best_r:
        best, best_r = cur, cur_r

    # Multi-start: perturb best and re-refine while budget remains.
    while time.process_time() < deadline:
        scale = 0.05 + 0.2 * rng.random()
        trial = best * (1.0 + scale * rng.standard_normal(best.size))
        trial = np.maximum(trial, 0.0)
        if trial.sum() <= 0:
            continue
        r = _R(trial)
        trial, r = refine(trial, r, rng, deadline)
        if r > best_r:
            best, best_r = trial, r

    best = np.maximum(best, 0.0)
    if best.sum() <= 0:
        best = np.ones(50)
    return best

